{
  "findings": [
    {
      "check_id": "CKV_AWS_364",
      "title": "Ensure that AWS Lambda function permissions delegated to AWS services are limited by SourceArn or SourceAccount",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "MEDIUM",
      "explanation": "The aws_lambda_permission resource allows API Gateway to invoke the Lambda function, but it does not restrict the permission to a specific API Gateway resource using SourceArn. This could allow unintended API Gateway resources to invoke the Lambda function, increasing the risk of unauthorized access."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_arn    = \"arn:aws:execute-api:${var.region}:${var.account_id}:${aws_api_gateway_rest_api.my_api.id}/*/*/*\"\n}",
  "fix_summary": "Added a 'source_arn' attribute to restrict the Lambda invocation permission to a specific API Gateway resource."
}
